Path('src/game/strokeBudget.test.ts').write_text('''import { describe, expect, it } from 'vitest';
import type { MatchSettings } from '../contracts/game';
import type { Course, Hole } from '../courses/types';
import { MatchManager } from '../gameplay/MatchManager';
import {
  DEFAULT_MAX_SHOTS_OVER_PAR,
  STROKE_LIMIT_PENALTY_STROKES,
  resolveMaxShots,
  resolveMaxShotsDetailed,
  strokeLimitScore,
} from '../gameplay/StrokeLimit';
import { COURSES, resolveCourse } from './CourseRegistry';

/** Settings the game builds for a match: no flat stroke limit is pinned. */
const settings: MatchSettings = { courseId: 'green-hills', maxPlayers: 8 };

const allHoles = (): Hole[] => COURSES.flatMap((course) => course.holes);
const parFiveHole = (): Hole => {
  const hole = allHoles().find((entry) => entry.par === 5 && entry.maxShots === undefined);
  expect(hole).toBeDefined();
  return hole!;
};

describe('hole shot budgets', () => {
  it('gives a par 5 hole without maxShots par + 7 shots and a penalty score one over the budget', () => {
    const hole = parFiveHole();
    expect(DEFAULT_MAX_SHOTS_OVER_PAR).toBe(7);
    expect(resolveMaxShots(hole, settings)).toBe(12);
    expect(resolveMaxShotsDetailed(hole, settings).source).toBe('par');
    expect(strokeLimitScore(resolveMaxShots(hole, settings))).toBe(13);
  });

  it('keeps the budget declared by the hole data', () => {
    const hole = resolveCourse('green-hills').holes.find((entry) => entry.id === 'gh-01-meadow-line')!;
    expect(hole.maxShots).toBe(6);
    expect(resolveMaxShots(hole, settings)).toBe(6);
    expect(resolveMaxShotsDetailed(hole, settings).source).toBe('hole');
  });

  it('never resolves a flat budget across the shipped courses', () => {
    for (const hole of allHoles()) {
      expect(resolveMaxShots(hole, settings)).toBe(hole.maxShots ?? hole.par + DEFAULT_MAX_SHOTS_OVER_PAR);
    }
  });

  it('books maxShots + 1 strokes when a par 5 hole runs out of shots', () => {
    const hole = parFiveHole();
    const course: Course = { id: 'budget-test', name: 'Budget Test', themeId: 'green-hills', version: 1, holes: [hole] };
    const manager = new MatchManager();
    let match = manager.createMatch('m1', { courseId: course.id, maxPlayers: 2 }, [
      { id: 'p1', displayName: 'P1', kind: 'human', ballStyleId: 'default', rating: 1000 },
    ]);
    match = manager.startMatch(match, course, 0);
    match = manager.beginAiming(match, hole);

    for (let index = 1; index <= 12; index += 1) {
      match = manager.markShotSubmitted(match);
      match = manager.applySimulationEvent(match, course, {
        type: 'shot-accepted',
        command: {
          playerId: 'p1',
          holeId: hole.id,
          direction: { x: 1, y: 0, z: 0 },
          normalizedPower: 0.5,
          clientSequence: index,
          issuedAt: 0,
        },
      }, 0);
      match = manager.applySimulationEvent(match, course, {
        type: 'ball-stopped',
        playerId: 'p1',
        position: { x: 1, y: 0, z: 0 },
      }, 100 * index);
    }

    const score = match.players[0]!.holeScores.find((entry) => entry.holeId === hole.id)!;
    expect(score.completed).toBe(true);
    expect(score.strokeLimitReached).toBe(true);
    expect(score.strokes).toBe(13);
    expect(score.penaltyStrokes).toBe(STROKE_LIMIT_PENALTY_STROKES);
  });
});
''')
